        return sum(1 for s, e in zip(startTime, endTime) if s <= queryTime <= e)

#include <vector>

class Solution {
public:
    int busyStudent(std::vector<int>& startTime, std::vector<int>& endTime, int queryTime) {
        int count = 0;
        for (int i = 0; i < (int)startTime.size(); ++i) {
            if (startTime[i] <= queryTime && queryTime <= endTime[i]) count++;
        }
        return count;
    }
};

class Solution {
    public int busyStudent(int[] startTime, int[] endTime, int queryTime) {
        int count = 0;
        for (int i = 0; i < startTime.length; i++) {
            if (startTime[i] <= queryTime && queryTime <= endTime[i]) count++;
        }
        return count;
    }
}

